// Offline support. Every file of one version is saved together when that version installs, and the app always opens
// from that saved set: instant, even on a slow connection, and never a mix of old and new files. A new version
// arrives as a whole (the browser notices when this file changes) and the page offers to reload.
// VERSION and ASSETS are generated by scripts/stamp-sw.mjs (runs on `npm start` and on every deploy):
// VERSION is a fingerprint of the app files, so any change makes phones fetch the new version.
const VERSION = 'chord-coach-6d8d93e6f7';
const ASSETS = [
  './',
  'icons/icon-180.png',
  'icons/icon-192.png',
  'icons/icon-512.png',
  'icons/icon.svg',
  'index.html',
  'js/analyze.js',
  'js/app.js',
  'js/audio.js',
  'js/backup.js',
  'js/chord-detect.js',
  'js/dom.js',
  'js/falling.js',
  'js/fingering.js',
  'js/fingers.js',
  'js/keyboard.js',
  'js/live-keys.js',
  'js/melody.js',
  'js/midi.js',
  'js/musicxml.js',
  'js/notation-text.js',
  'js/note-quiz.js',
  'js/piece.js',
  'js/player.js',
  'js/practice.js',
  'js/recorder.js',
  'js/rhythm.js',
  'js/sheet.js',
  'js/store.js',
  'js/style.js',
  'js/theory.js',
  'js/tune-sheet.js',
  'js/ultimate-guitar.js',
  'js/views/chords.js',
  'js/views/count-grid.js',
  'js/views/maker.js',
  'js/views/note-quiz.js',
  'js/views/piano.js',
  'js/views/practice-controls.js',
  'js/views/quiz.js',
  'js/views/record-card.js',
  'js/views/sheets.js',
  'js/views/songs.js',
  'js/views/stage.js',
  'js/views/tune.js',
  'js/views/type-entry.js',
  'js/views/wait-run.js',
  'js/volume.js',
  'js/wait-mode.js',
  'manifest.webmanifest',
  'reset.html',
  'styles.css',
];

self.addEventListener('install', e => {
  // cache: 'reload' skips the browser's own HTTP cache, so a new version can never save old files.
  e.waitUntil(
    caches.open(VERSION)
      .then(c => Promise.all(ASSETS.map(a => c.add(new Request(a, { cache: 'reload' })))))
      .then(() => self.skipWaiting()),
  );
});

self.addEventListener('activate', e => {
  e.waitUntil(
    caches.keys()
      .then(keys => Promise.all(keys.filter(k => k !== VERSION).map(k => caches.delete(k))))
      .then(() => self.clients.claim()),
  );
});

self.addEventListener('fetch', e => {
  const url = new URL(e.request.url);
  if (e.request.method !== 'GET' || url.origin !== location.origin) return;
  e.respondWith((async () => {
    const cache = await caches.open(VERSION);
    const saved = await cache.match(e.request, { ignoreSearch: true });
    if (saved) return saved;
    try {
      return await fetch(e.request); // not part of the app (nothing saved for it): ask the internet
    } catch {
      return e.request.mode === 'navigate' ? (await cache.match('index.html')) || Response.error() : Response.error();
    }
  })());
});
